import os
import secrets
import hashlib
import base64
from urllib.parse import urlencode

from authlib.integrations.flask_client import OAuth
from flask import Flask, redirect, request, session, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("FLASK_SECRET_KEY", secrets.token_hex(32))

AUTH0_DOMAIN = os.environ["AUTH0_DOMAIN"]
AUTH0_CLIENT_ID = os.environ["AUTH0_CLIENT_ID"]
AUTH0_CLIENT_SECRET = os.environ["AUTH0_CLIENT_SECRET"]
AUTH0_CALLBACK_URL = os.environ.get("AUTH0_CALLBACK_URL", "http://localhost:5000/callback")
AUTH0_AUDIENCE = os.environ.get("AUTH0_AUDIENCE")

oauth = OAuth(app)
oauth.register(
    name="auth0",
    client_id=AUTH0_CLIENT_ID,
    client_secret=AUTH0_CLIENT_SECRET,
    server_metadata_url=f"https://{AUTH0_DOMAIN}/.well-known/openid-configuration",
    client_kwargs={"scope": "openid profile email"},
)

def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def _create_pkce_pair():
    verifier = _b64url(secrets.token_bytes(32))
    challenge = _b64url(hashlib.sha256(verifier.encode("ascii")).digest())
    return verifier, challenge

@app.route("/login")
def login():
    state = secrets.token_urlsafe(32)
    nonce = secrets.token_urlsafe(32)
    code_verifier, code_challenge = _create_pkce_pair()

    session["oidc_state"] = state
    session["oidc_nonce"] = nonce
    session["pkce_code_verifier"] = code_verifier

    authorize_params = {
        "state": state,
        "nonce": nonce,
        "code_challenge": code_challenge,
        "code_challenge_method": "S256",
    }
    if AUTH0_AUDIENCE:
        authorize_params["audience"] = AUTH0_AUDIENCE

    return oauth.auth0.authorize_redirect(
        redirect_uri=AUTH0_CALLBACK_URL,
        **authorize_params,
    )

@app.route("/callback")
def callback():
    if request.args.get("state") != session.get("oidc_state"):
        return jsonify({"error": "invalid_state"}), 400

    token = oauth.auth0.authorize_access_token(
        code_verifier=session.get("pkce_code_verifier")
    )

    userinfo = oauth.auth0.userinfo(token=token)
    expected_nonce = session.get("oidc_nonce")
    returned_nonce = None
    if isinstance(token, dict):
        returned_nonce = token.get("userinfo", {}).get("nonce") or token.get("nonce")

    if returned_nonce is not None and returned_nonce != expected_nonce:
        return jsonify({"error": "invalid_nonce"}), 400

    session.pop("oidc_state", None)
    session.pop("oidc_nonce", None)
    session.pop("pkce_code_verifier", None)

    return jsonify(
        {
            "provider": "Auth0",
            "issuer": f"https://{AUTH0_DOMAIN}/",
            "access_token": token.get("access_token"),
            "id_token": token.get("id_token"),
            "userinfo": dict(userinfo),
        }
    )

@app.route("/logout")
def logout():
    session.clear()
    params = {
        "client_id": AUTH0_CLIENT_ID,
        "returnTo": request.host_url.rstrip("/"),
    }
    return redirect(f"https://{AUTH0_DOMAIN}/v2/logout?{urlencode(params)}")

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", "5000")))
